// ListFunc is a function which can return a set of results for a list request.
type ListFunc[P, V any] func(context.Context, *ListRequest[P]) (ResultSet[V], error)

type ListAllParams struct {
	PerPage int
	Order   Order
}

// ListAll can return the entire contents of some generic storage layer if given
// a ListFunc implementation for that store.
// It performs an entire paginated walk until an empty next page token is returned.
func ListAll[P, V any](ctx context.Context, fn ListFunc[P, V], params ListAllParams) (res []V, err error) {
	var req *ListRequest[P]

	for {
		if req != nil && req.QueryParams.PageToken == "" {
			break
		}

		if req == nil {
			req = &ListRequest[P]{
				QueryParams: QueryParams{
					Limit: uint64(params.PerPage),
					Order: params.Order,
				},
			}
		}

		set, err := fn(ctx, req)
		if err != nil {
			return nil, err
		}

		req.QueryParams.PageToken = set.NextPageToken
		res = append(res, set.Results...)
	}

	return res, nil
}
// PageParameter is any type which exposes limit and page token
// accessors used to identify pages.
type PageParameter interface {
	GetLimit() int32
	GetPageToken() string
}

// OffsetPageParameter is a type which exposes an additional offset
// accessor for legacy paging implementations (page token supersedes).
type OffsetPageParameter interface {
	PageParameter
	GetOffset() int32
}

// ListWithParameters constructs a new ListRequest using the page parameters
// exposed by the provided PageParameter implementation.
func ListWithParameters[T any](t T, p PageParameter) *ListRequest[T] {
	opts := []QueryOption{
		WithLimit(uint64(p.GetLimit())),
		WithPageToken(p.GetPageToken()),
	}

	if po, ok := p.(OffsetPageParameter); ok {
		opts = append(opts, WithOffset(uint64(po.GetOffset())))
	}

	return ListWithOptions[T](t, ListWithQueryParamOptions[T](opts...))
}

// ListWithOptions constructs a new ListRequest using the provided ListOption.
func ListWithOptions[T any](t T, opts ...ListOption[T]) *ListRequest[T] {
	req := &ListRequest[T]{
		Predicate: t,
	v, err := strconv.ParseInt(params.PageToken, 10, 64)
	if params.PageToken != "" && err != nil {
		return storage.ResultSet[T]{}, errs.ErrInvalidf("pageToken is not valid: %q", params.PageToken)
	}

	offset = int(v)

	if offset >= len(set.Results) {
		return storage.ResultSet[T]{}, errs.ErrInvalidf("invalid offset: %d", offset)
	}

	// 0 means no limit on page size (all items from offset)
	if params.Limit == 0 {
		set.Results = set.Results[offset:]
		return set, nil
	}

	// ensure end of page does not exceed entire set
	end := offset + int(params.Limit)
	if end > len(set.Results) {
		end = len(set.Results)
	} else if end < len(set.Results) {
		// set next page token given there are more entries
		set.NextPageToken = fmt.Sprintf("%d", end)
	}

	// reduce results set to requested page
	set.Results = set.Results[offset:end]

	return set, nil
}

